    {{-- SCRIPTS THEO DÕI HOVER ĐỂ HIỆN TOOLTIP --}}
    @script
    <script>
        document.addEventListener('mouseover', function(e) {
            let path = e.target.closest('#features path[id^="LK"]');
            if (!path) return;

            let container = document.getElementById('lk-map-container');
            let tooltip = document.getElementById('lk-tooltip');
            let mapData = JSON.parse(container.getAttribute('data-mapdata'));

            let svgId = path.getAttribute('id');
            let info = mapData[svgId];

            if (info) {
                let userLabel = document.querySelector('select[wire\\:model\\.live="userType"]').value === 'cgo' ? 'CGOs' : 'Trainees';

                tooltip.innerHTML = `
                    <div style="min-width: 140px;">
                        <div class="pb-1 mb-1 font-bold border-b border-gray-600 text-md">${info.name}</div>
                        <div class="flex justify-between gap-4 text-xs">
                            <span class="text-gray-300">${userLabel}:</span>
                            <span class="font-bold" style="color: ${info.color === '#f3f4f6' ? '#fff' : info.color}">${info.count}</span>
                        </div>
                        <div class="flex justify-between gap-4 mt-1 text-xs">
                            <span class="text-gray-300">Share:</span>
                            <span>${info.percentage}%</span>
                        </div>
                    </div>
                `;
                tooltip.style.display = 'block';
            }
        });

        document.addEventListener('mousemove', function(e) {
            let tooltip = document.getElementById('lk-tooltip');
            let container = document.getElementById('lk-map-container');

            if (tooltip && tooltip.style.display === 'block' && container) {
                let rect = container.getBoundingClientRect();
                tooltip.style.left = (e.clientX - rect.left + 15) + 'px';
                tooltip.style.top = (e.clientY - rect.top + 15) + 'px';
            }
        });

        document.addEventListener('mouseout', function(e) {
            if (e.target.closest('#features path')) {
                document.getElementById('lk-tooltip').style.display = 'none';
            }
        });
    </script>
    @endscript
</x-filament::widget>
